/**
 * Phase 4.4 inbox type definitions.
 *
 * Files on disk are the source of truth. These types model both the
 * parsed-file representation (`MailFile*`) and the projected DB row
 * shape (`InboxMessage`, `OutboxMessage`, `Draft`, `AgentRoute`).
 *
 * API boundary convention:
 *   - The stable identifier callers use everywhere is a TEXT
 *     `{date}-{from-slug}-{subject-slug}-{hex4}` id generated by the
 *     engine on send or lifted from frontmatter on projection.
 *   - `inbox_messages` has a separate INTEGER primary key (`rowId`)
 *     only because FTS5 external-content tables hinge on a stable
 *     INTEGER rowid. It is private to the projection layer; every
 *     public method takes/returns the TEXT `id` instead.
 */

export type MessageKind = "message" | "task" | "notice" | "reply";
export type MessagePriority = "low" | "normal" | "high" | "urgent";
export type InboxStatus = "unread" | "read" | "tombstoned";
export type DeliveryStatus = "delivered" | "unrouted" | "failed";
export type DraftStatus = "draft" | "ready";
export type RouteOrigin = "config" | "operator" | "auto" | "self";

/**
 * The shape of frontmatter as it lives in the `.md` file. This is what
 * parseMailFile emits and what serializeMailFile consumes. Fields are
 * optional at the file level and defaulted at parse time — a file is
 * valid as long as `id`, `from`, `to`, and `date` are present.
 */
export interface MailFrontmatter {
  id: string;
  from_auth?: string;
  from: string;
  /**
   * Target recipient agent id. Optional in the file because older
   * inbox files predate this field (the file's physical
   * location in {mail_root}/inbox/ implies the recipient). Projector
   * fills it in from the owning mailbox's agent id at projection time.
   */
  to?: string;
  subject?: string;
  date: string;                       // ISO 8601
  priority?: MessagePriority;
  kind?: MessageKind;
  thread_id?: string;
  in_reply_to?: string;
  metadata?: Record<string, unknown>;
  /** Drafts set this; inbox/outbox omit it. */
  draft_status?: DraftStatus;
  /** Outbox copies only — populated at send time. */
  delivery_status?: DeliveryStatus;
  delivery_error?: string;
  to_mail_root?: string;
}

/**
 * What lives under `{mail_root}/`.
 *
 *   inbox/{id}.md                                        → source='inbox', status='unread'
 *   inbox/{id}/message.md (+ sibling attachments)        → source='inbox', status='unread'
 *   inbox/read/{id}.md                                   → source='inbox', status='read'
 *   inbox/read/{id}/message.md                           → source='inbox', status='read'
 *   inbox/tombstoned/{id}.md                             → source='inbox', status='tombstoned'
 *   inbox/tombstoned/{id}/message.md                     → source='inbox', status='tombstoned'
 *   outbox/{id}.md  OR  outbox/{id}/message.md           → source='outbox'
 *   drafts/{id}.md  OR  drafts/{id}/message.md           → source='drafts'
 */
export type MailSource =
  | "inbox"
  | "inbox/read"
  | "inbox/tombstoned"
  | "outbox"
  | "drafts";

export interface DiscoveredMailFile {
  absPath: string;
  relPath: string;         // relative to mail_root, e.g. "inbox/2026-04-17-foo.md"
  source: MailSource;
  /** Parent directory when multi-file message; null for single-file `{id}.md`. */
  messageDir: string | null;
  mtime: number;
  size: number;
}

export interface ParsedMailFile {
  frontmatter: MailFrontmatter;
  body: string;
  attachments: Array<{
    filename: string;
    absPath: string;
    relPath: string;
    sizeBytes: number;
    sha256: string;
    contentType: string | null;
  }>;
  source: MailSource;
  relPath: string;
  sha256: string;
  mtime: number;
}

// ============================================================================
// DB row shapes (projected)
// ============================================================================

export interface InboxMessage {
  id: string;                          // message_id (frontmatter-level)
  ownerAgentId: string;
  relPath: string;
  fromAuth: string;
  fromDisplay: string;                 // frontmatter `from`
  toAgent: string;
  subject: string | null;
  priority: MessagePriority | null;
  kind: MessageKind;
  threadId: string | null;
  inReplyTo: string | null;
  metadata: Record<string, unknown> | null;
  body: string;
  status: InboxStatus;
  dateIso: string;
  dateMs: number;
  fileMtime: number;
  fileSha256: string;
  projectedAt: number;
  attachments: InboxAttachment[];
}

export interface InboxAttachment {
  id: number;
  messageId: string;
  filename: string;
  relPath: string;
  contentType: string | null;
  sizeBytes: number;
  sha256: string;
}

export interface OutboxMessage {
  id: string;
  ownerAgentId: string;
  relPath: string;
  toAgent: string;
  toMailRoot: string;
  fromDisplay: string;
  subject: string | null;
  body: string;
  kind: MessageKind;
  threadId: string | null;
  sentAtIso: string;
  sentAtMs: number;
  deliveryStatus: DeliveryStatus;
  deliveryError: string | null;
  fileMtime: number;
  fileSha256: string;
  projectedAt: number;
}

export interface Draft {
  id: string;
  ownerAgentId: string;
  relPath: string;
  toAgent: string | null;
  fromDisplay: string | null;
  subject: string | null;
  body: string;
  priority: MessagePriority | null;
  kind: MessageKind;
  metadata: Record<string, unknown> | null;
  authorAuth: string;
  status: DraftStatus;
  createdAtIso: string;
  updatedAtIso: string;
  createdAtMs: number;
  updatedAtMs: number;
  fileMtime: number;
  fileSha256: string;
  projectedAt: number;
}

export interface AgentRoute {
  agentId: string;
  mailRoot: string;                    // expanded absolute path
  displayName: string;
  avatarPath: string | null;
  capabilities: string[] | null;
  lastSeenAt: number | null;
  createdBy: RouteOrigin;
  createdAt: number;
  updatedAt: number;
}

// ============================================================================
// Engine input / output shapes
// ============================================================================

export interface NewAttachmentInput {
  filename: string;
  /** Absolute path on disk the engine reads bytes from at send time. */
  sourceAbsPath: string;
  contentType?: string;
}

export interface SendOpts {
  to: string;
  from: string;                        // frontmatter `from` (display)
  fromAuth: string;                    // "agent:<id>" | "operator:<token-id>"
  subject?: string;
  body: string;
  priority?: MessagePriority;
  kind?: MessageKind;
  threadId?: string;
  inReplyTo?: string;
  metadata?: Record<string, unknown>;
  attachments?: NewAttachmentInput[];
  /** Override the id generator — tests/import-tools use this. */
  idOverride?: string;
  /** Override now() — tests use this. */
  now?: number;
}

export interface SendResult {
  messageId: string;
  relPath: string;                     // relative to recipient's mail_root
  deliveryStatus: DeliveryStatus;
  deliveryError: string | null;
  deliveredTo: string;                 // agent_id actually written to ("operator" on fallback)
  deliveredMailRoot: string;
  outboxRetained: boolean;
  outboxRelPath: string | null;
  /**
   * Phase 4.4b: when deliveryStatus="unrouted", the list of known peer
   * routes (excluding self/operator/owner) so the caller can tell the
   * LLM/operator which agents *do* have routes. Undefined on successful
   * delivery — the info is only useful when the send missed.
   */
  availableRoutes?: Array<{
    agentId: string;
    displayName: string;
    capabilities: string[] | null;
  }>;
}

export interface AgentRouteInput {
  agentId: string;
  mailRoot: string;
  displayName: string;
  avatarPath?: string | null;
  capabilities?: string[];
  createdBy?: RouteOrigin;
}

export interface DraftInput {
  to?: string | null;
  from?: string | null;
  fromAuth: string;
  subject?: string | null;
  body: string;
  priority?: MessagePriority | null;
  kind?: MessageKind;
  metadata?: Record<string, unknown> | null;
  /** Override id — tests use this. */
  idOverride?: string;
}

export interface DraftPatch {
  to?: string | null;
  from?: string | null;
  subject?: string | null;
  body?: string;
  priority?: MessagePriority | null;
  kind?: MessageKind;
  metadata?: Record<string, unknown> | null;
  status?: DraftStatus;
}

export interface InboxListOpts {
  status?: InboxStatus | "all";        // default 'unread'
  kind?: MessageKind[];
  priority?: MessagePriority[];
  threadId?: string;
  from?: string;                       // exact match on from_display
  limit?: number;
  offset?: number;
}

export interface InboxStatusSummary {
  unreadCount: number;
  unreadSenders: string[];
  hasPriority: boolean;
}

export interface InboxSearchOpts extends InboxListOpts {
  q: string;
}

export interface OutboxListOpts {
  limit?: number;
  offset?: number;
  deliveryStatus?: DeliveryStatus[];
}

export interface DraftListOpts {
  limit?: number;
  offset?: number;
  status?: DraftStatus;
}

/**
 * What one projection tick actually did. Surfaced from
 * `projector.projectOnce()` so tests + runtime logging can report.
 */
export interface ProjectionResult {
  scanned: number;
  added: number;
  updated: number;
  removed: number;
  skippedMalformed: number;
  durationMs: number;
}

// ============================================================================
// Config
// ============================================================================

export interface InboxConfigInput {
  enabled?: boolean;
  mail_root?: string;
  poll_interval_seconds?: number;
  operator_mail_root?: string;
  contacts?: Array<{
    agent_id: string;
    mail_root: string;
    display_name?: string;
    avatar_path?: string;
    capabilities?: string[];
  }>;
}

export interface ResolvedInboxConfig {
  mailRoot: string;                    // absolute
  operatorMailRoot: string;            // absolute
  pollIntervalMs: number;
  contacts: AgentRouteInput[];
  agentId: string;
  agentDisplayName: string;
}
